            var mid = (lo + hi + 1) / 2;
            if (font.GetStringSize(text[..mid] + "…", HorizontalAlignment.Left, -1, size).X <= maxWidth) lo = mid;
            else hi = mid - 1;
        }
        return text[..lo] + "…";"}]}

